insert into public.products (category_id, slug, name, summary, description, price, stock, specs, image_url, devicemart_no, is_featured)
select c.id, v.slug, v.name, v.summary, v.description, v.price, v.stock, v.specs, v.image_url, v.devicemart_no, v.is_featured
from (values
  ('boards', 'uno-r4-minima', 'Arduino UNO R4 Minima (정품)', '우노 R3 호환 폼팩터의 32비트 차세대 우노 보드', '우노 R3 호환 폼팩터의 32비트 차세대 우노 보드. 가격과 사양은 디바이스마트 판매 정보를 기준으로 정리했습니다.', 26950, 30, '{"MCU":"Renesas RA4M1 (Cortex-M4)","클럭":"48MHz","메모리":"256KB Flash / 32KB RAM","포트":"USB-C"}'::jsonb, '/images/products/uno-r4-minima.jpg', 15088714, true),
  ('boards', 'uno-r4-wifi', 'Arduino UNO R4 WiFi (정품)', 'ESP32-S3 내장 와이파이·블루투스 지원 우노 R4', 'ESP32-S3 내장 와이파이·블루투스 지원 우노 R4. 가격과 사양은 디바이스마트 판매 정보를 기준으로 정리했습니다.', 42130, 25, '{"MCU":"RA4M1 + ESP32-S3","무선":"Wi-Fi / Bluetooth","디스플레이":"12x8 LED 매트릭스","포트":"USB-C"}'::jsonb, '/images/products/uno-r4-wifi.jpg', 15088648, true),
  ('boards', 'uno-r3', 'Arduino UNO R3 (정품)', '가장 많이 쓰이는 아두이노 표준 보드 (이탈리아 정품)', '가장 많이 쓰이는 아두이노 표준 보드 (이탈리아 정품). 가격과 사양은 디바이스마트 판매 정보를 기준으로 정리했습니다.', 31900, 40, '{"MCU":"ATmega328P","디지털 I/O":"14핀","아날로그 입력":"6핀","동작전압":"5V"}'::jsonb, '/images/products/uno-r3.jpg', 34404, false),
  ('boards', 'nano-every', 'Arduino Nano Every (정품)', '작고 강력한 나노 폼팩터 아두이노', '작고 강력한 나노 폼팩터 아두이노. 가격과 사양은 디바이스마트 판매 정보를 기준으로 정리했습니다.', 20790, 20, '{"MCU":"ATMega4809","동작전압":"5V","크기":"45 x 18mm","헤더":"미포함"}'::jsonb, '/images/products/nano-every.jpg', 12229355, false),
  ('boards', 'nano-esp32', 'Arduino Nano ESP32 (정품)', 'ESP32-S3 기반 IoT·마이크로파이썬용 나노 보드', 'ESP32-S3 기반 IoT·마이크로파이썬용 나노 보드. 가격과 사양은 디바이스마트 판매 정보를 기준으로 정리했습니다.', 27390, 18, '{"MCU":"ESP32-S3 (NORA-W106)","무선":"Wi-Fi / Bluetooth LE","I/O 전압":"3.3V","포트":"USB-C"}'::jsonb, '/images/products/nano-esp32.jpg', 15139460, true),
  ('boards', 'mega-2560', 'Arduino Mega 2560 R3 (정품)', '핀이 많은 대형 프로젝트용 메가 보드 (이탈리아 정품)', '핀이 많은 대형 프로젝트용 메가 보드 (이탈리아 정품). 가격과 사양은 디바이스마트 판매 정보를 기준으로 정리했습니다.', 64900, 15, '{"MCU":"ATmega2560","디지털 I/O":"54핀","아날로그 입력":"16핀","동작전압":"5V"}'::jsonb, '/images/products/mega-2560.jpg', 34405, false),
  ('boards', 'uno-compatible', '아두이노 우노 R3 호환보드 (CH340)', '우노 R3와 동일 기능의 저가형 호환 보드', '우노 R3와 동일 기능의 저가형 호환 보드. 가격과 사양은 디바이스마트 판매 정보를 기준으로 정리했습니다.', 6050, 120, '{"MCU":"ATmega328P","USB 칩":"CH340 (드라이버 필요)","동작전압":"5V"}'::jsonb, '/images/products/uno-compatible.jpg', 1357630, true),
  ('sensors', 'hc-sr04', 'HC-SR04 초음파 거리센서 모듈', '초음파로 거리를 측정하는 센서 모듈', '초음파로 거리를 측정하는 센서 모듈. 가격과 사양은 디바이스마트 판매 정보를 기준으로 정리했습니다.', 1210, 200, '{"측정거리":"2cm ~ 500cm","동작전압":"5V","인터페이스":"Trig / Echo"}'::jsonb, '/images/products/hc-sr04.jpg', 1076851, true),
  ('sensors', 'dht11', 'DHT11 온습도 센서 모듈', '온도·습도를 디지털 신호로 출력하는 센서 (케이블 포함)', '온도·습도를 디지털 신호로 출력하는 센서 (케이블 포함). 가격과 사양은 디바이스마트 판매 정보를 기준으로 정리했습니다.', 1760, 150, '{"측정":"온도 / 습도","출력":"디지털 단일 버스","구성":"케이블 포함"}'::jsonb, '/images/products/dht11.jpg', 1278926, false),
  ('sensors', 'pir-hc-sr501', 'HC-SR501 PIR 인체감지 센서', '적외선으로 사람의 움직임을 감지하는 센서 모듈', '적외선으로 사람의 움직임을 감지하는 센서 모듈. 가격과 사양은 디바이스마트 판매 정보를 기준으로 정리했습니다.', 1650, 150, '{"방식":"PIR 적외선","출력":"디지털 (HIGH/LOW)","조정":"감도·지연시간 가변"}'::jsonb, '/images/products/pir-hc-sr501.jpg', 1287086, false),
  ('sensors', 'soil-moisture', '토양 수분 센서 모듈', '토양의 습도를 측정하는 센서 (A/D 컨버터 포함)', '토양의 습도를 측정하는 센서 (A/D 컨버터 포함). 가격과 사양은 디바이스마트 판매 정보를 기준으로 정리했습니다.', 1100, 180, '{"측정":"토양 습도","출력":"아날로그 / 디지털","구성":"프로브 + 컨버터 보드"}'::jsonb, '/images/products/soil-moisture.jpg', 1376532, false),
  ('modules', 'sg90-servo', 'SG90 9g 미니 서보모터', '가장 많이 쓰이는 소형 서보모터 (TowerPro 호환)', '가장 많이 쓰이는 소형 서보모터 (TowerPro 호환). 가격과 사양은 디바이스마트 판매 정보를 기준으로 정리했습니다.', 2090, 220, '{"토크":"1.8kg·cm (4.8V)","속도":"0.1초/60°","무게":"9g"}'::jsonb, '/images/products/sg90-servo.jpg', 1128421, true),
  ('modules', 'lcd-1602-i2c', '1602 I2C LCD 모듈', 'I2C로 간편 연결하는 16x2 문자 LCD', 'I2C로 간편 연결하는 16x2 문자 LCD. 가격과 사양은 디바이스마트 판매 정보를 기준으로 정리했습니다.', 2750, 90, '{"표시":"16 x 2 문자","인터페이스":"I2C","백라이트":"Blue / 흰색 문자","크기":"80 x 36mm"}'::jsonb, '/images/products/lcd-1602-i2c.jpg', 1327456, true),
  ('modules', 'relay-module', '1채널 5V 릴레이 모듈', '아두이노로 고전압 부하를 켜고 끄는 릴레이', '아두이노로 고전압 부하를 켜고 끄는 릴레이. 가격과 사양은 디바이스마트 판매 정보를 기준으로 정리했습니다.', 1210, 160, '{"코일 전압":"5V","최대 부하":"AC 250V/10A, DC 30V/10A","크기":"50 x 26 x 18.5mm"}'::jsonb, '/images/products/relay-module.jpg', 1320897, false),
  ('modules', 'l298n', 'L298N 모터 드라이버 모듈', 'DC모터 2개를 제어하는 듀얼 H-브리지 드라이버', 'DC모터 2개를 제어하는 듀얼 H-브리지 드라이버. 가격과 사양은 디바이스마트 판매 정보를 기준으로 정리했습니다.', 2970, 110, '{"칩":"ST L298N","동작전압":"5V ~ 35V","전류":"최대 2A (채널당)","채널":"2"}'::jsonb, '/images/products/l298n.jpg', 1278835, false),
  ('kits', 'starter-kit', 'Arduino Starter Kit 한글판 (정품)', '15가지 프로젝트 가이드북 포함 공식 입문 키트', '15가지 프로젝트 가이드북 포함 공식 입문 키트. 가격과 사양은 디바이스마트 판매 정보를 기준으로 정리했습니다.', 152900, 8, '{"모델":"K120007","구성":"UNO + 기초 부품","가이드북":"한글, 15개 프로젝트","동작전압":"5V"}'::jsonb, '/images/products/starter-kit.jpg', 1149109, true),
  ('parts', 'breadboard', '830홀 브레드보드 (MB-102)', '납땜 없이 회로를 구성하는 표준 브레드보드', '납땜 없이 회로를 구성하는 표준 브레드보드. 가격과 사양은 디바이스마트 판매 정보를 기준으로 정리했습니다.', 1540, 300, '{"규격":"830핀 MB-102","크기":"165 x 55 x 8.5mm"}'::jsonb, '/images/products/breadboard.jpg', 1322408, false),
  ('parts', 'jumper-wires', '점퍼 케이블 M-M 40P (20cm)', '브레드보드 연결용 컬러 점퍼 케이블 40가닥', '브레드보드 연결용 컬러 점퍼 케이블 40가닥. 가격과 사양은 디바이스마트 판매 정보를 기준으로 정리했습니다.', 940, 400, '{"타입":"Male - Male","수량":"40P","길이":"20cm","피치":"2.54mm"}'::jsonb, '/images/products/jumper-wires.jpg', 1321196, false),
  ('parts', 'led-set', '일반 LED 6종 키트 (3mm/5mm)', '3mm·5mm 3색 라운드 LED 구성 키트', '3mm·5mm 3색 라운드 LED 구성 키트. 가격과 사양은 디바이스마트 판매 정보를 기준으로 정리했습니다.', 2420, 250, '{"구성":"3mm 3색 + 5mm 3색","형태":"라운드 LED"}'::jsonb, '/images/products/led-set.jpg', 1313539, false)
) as v(category, slug, name, summary, description, price, stock, specs, image_url, devicemart_no, is_featured)
join public.categories c on c.slug = v.category
on conflict (slug) do update set price = excluded.price, summary = excluded.summary, specs = excluded.specs;
